import Foundation
import UIKit

// The brownfield E2E host imports only this framework, as the brownfield
// guide describes: Hot Updater and React stay internal.
@_exported import ReactBrownfield
internal import HotUpdater
internal import React

/// The framework's bundle: its `main.jsbundle` and `HOT_UPDATER_*` keys.
public let ReactNativeBundle = Bundle(for: InternalClassForBundle.self)

class InternalClassForBundle {}

/// Starts React Native with Hot Updater choosing the JavaScript bundle.
@MainActor
public func startReactNativeWithHotUpdater(
  launchOptions: [UIApplication.LaunchOptionsKey: Any]?
) {
  ReactNativeBrownfield.shared.bundle = ReactNativeBundle
  ReactNativeBrownfield.shared.bundleURLOverride = {
    HotUpdater.bundleURL(bundle: ReactNativeBundle)
  }
  ReactNativeBrownfield.shared.startReactNative(
    launchOptions: launchOptions.map { options in
      Dictionary(uniqueKeysWithValues: options.map { (AnyHashable($0.key), $0.value) })
    },
    preloadBundle: false,
    onBundleLoaded: nil
  )
}

/// Hands a deep link to React Native's `Linking`.
@MainActor
public func openReactNativeURL(
  _ application: UIApplication,
  url: URL,
  options: [UIApplication.OpenURLOptionsKey: Any]
) -> Bool {
  RCTLinkingManager.application(application, open: url, options: options)
}

// Packages the example as an AAR for the brownfield E2E track, as React
// Native Brownfield's scaffold does (see the brownfield guide).
plugins {
    id("com.android.library")
    id("org.jetbrains.kotlin.android")
    id("com.callstack.react.brownfield")
    `maven-publish`
    id("com.facebook.react")
}

fun rootInt(name: String): Int = rootProject.extensions.extraProperties.get(name).toString().toInt()

publishing {
    publications {
        create<MavenPublication>("mavenAar") {
            groupId = "com.hotupdaterexample"
            artifactId = "brownfieldlib"
            version = "1.0.0"
            afterEvaluate {
                from(components.getByName("default"))
            }
        }
    }
    repositories {
        // A repository inside this build, so concurrent runs never share one.
        maven {
            name = "brownfieldE2e"
            url = uri(layout.buildDirectory.dir("maven"))
        }
    }
}

reactBrownfield {
    missingDimensionStrategies = listOf()
}

react {
    autolinkLibrariesWithApp()
}

android {
    namespace = "com.hotupdaterexample.brownfield"
    compileSdk = rootInt("compileSdkVersion")

    defaultConfig {
        minSdk = rootInt("minSdkVersion")
        consumerProguardFiles("consumer-rules.pro")
        // Read by React Native's generated entry point, as in an app module.
        buildConfigField("boolean", "IS_NEW_ARCHITECTURE_ENABLED", properties["newArchEnabled"].toString())
        buildConfigField("boolean", "IS_HERMES_ENABLED", properties["hermesEnabled"].toString())
        buildConfigField("boolean", "IS_EDGE_TO_EDGE_ENABLED", properties["edgeToEdgeEnabled"].toString())
    }

    buildFeatures {
        buildConfig = true
    }

    buildTypes {
        release {
            isMinifyEnabled = false
        }
    }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
    kotlinOptions {
        jvmTarget = "17"
    }

    publishing {
        multipleVariants {
            allVariants()
        }
    }
}

dependencies {
    implementation("org.jetbrains.kotlinx:kotlinx-coroutines-android:1.7.3")
    api("com.facebook.react:react-android:0.85.2")
    api("com.facebook.hermes:hermes-android:250829098.0.10")
}

package com.hotupdaterexample.brownfield

import android.app.Application
import com.callstack.reactnativebrownfield.ReactNativeBrownfield
import com.facebook.react.PackageList
import com.facebook.react.defaults.DefaultReactHost.getDefaultReactHost
import com.hotupdater.HotUpdater

/** Starts React Native for the brownfield E2E host, as the brownfield guide does. */
object ReactNativeHostManager {
    fun start(application: Application) {
        ReactNativeBrownfield.initialize(application) {
            getDefaultReactHost(
                context = application,
                packageList = PackageList(application).packages,
                jsMainModulePath = "index",
                jsBundleAssetPath = "index.android.bundle",
                jsBundleFilePath = HotUpdater.getJSBundleFile(application),
                useDevSupport = false,
                jsRuntimeFactory = null,
            )
        }
        HotUpdater.setReactHost(ReactNativeBrownfield.shared.reactHost)
    }
}
